<?php

// A local peer for client security tests. TLS certificates and keys are
// generated by the parent test and never used outside this fixture.
$mode = $argv[1];
$options = json_decode($argv[2] ?? '{}', true, flags: JSON_THROW_ON_ERROR);
$context = stream_context_create(isset($options['certificate']) ? [
    'ssl' => [
        'local_cert' => $options['certificate'],
        'local_pk' => $options['key'],
        'verify_peer' => false, // This fixture does not require client certificates.
    ],
] : []);
$listener = stream_socket_server('tcp://127.0.0.1:0', $errno, $error,
    STREAM_SERVER_BIND | STREAM_SERVER_LISTEN, $context);
if (!$listener) {
    throw new RuntimeException($error, $errno);
}
echo substr(strrchr(stream_socket_get_name($listener, false), ':'), 1), "\n";
fflush(STDOUT);
$connection = stream_socket_accept($listener, 3);
fclose($listener);
if (!$connection) {
    exit(1);
}
stream_set_timeout($connection, 3);
try {
    if ($mode === 'tls-stall' || $mode === 'no-read') {
        usleep((int) (($options['delay'] ?? 0.4) * 1e6));
        return;
    }
    if ($mode === 'plaintext-probe') {
        echo bin2hex(substr(fread($connection, 4096), 0, 16)), "\n";
        @fwrite($connection, "HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\nok");
        return;
    }
    if ($mode === 'tls' && @stream_socket_enable_crypto($connection, true, STREAM_CRYPTO_METHOD_TLS_SERVER) !== true) {
        return;
    }
    while (($line = fgets($connection)) !== false && $line !== "\r\n") {
    }
    $wire = match ($mode) {
        'slow-headers' => "HTTP/1.1 200 OK\r\nX-Slow: ",
        'slow-body' => "HTTP/1.1 200 OK\r\nContent-Length: 20\r\n\r\n",
        'slow-eof' => "HTTP/1.1 200 OK\r\n\r\n",
        'slow-trailers' => "HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n0\r\nX-Slow: ",
        'oversized-fixed' => "HTTP/1.1 200 OK\r\nContent-Length: 5\r\n\r\nhello",
        'oversized-chunked' => "HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n5\r\nhello\r\n0\r\n\r\n",
        'oversized-eof' => "HTTP/1.1 200 OK\r\n\r\nhello",
        default => "HTTP/1.1 200 OK\r\nContent-Length: 2\r\n\r\nok",
    };
    @fwrite($connection, $wire);
    if (str_starts_with($mode, 'slow-')) {
        for ($i = 0; $i < 20; $i++) {
            usleep(20000);
            if (@fwrite($connection, 'a') !== 1) {
                break;
            }
        }
    }
}
finally {
    fclose($connection);
}
